import {downloadSave,pickSave,importSave} from './save-transfer.mjs';
import {controlOpacity,saveControlOpacity} from './mobile-preferences.mjs';
import {MobileControlEditor} from './mobile-control-editor.mjs';
import {audioPreferences} from './audio-preferences.mjs';
import {redeemSavedGift,REDEEM_REWARDS} from './redeem-codes.mjs';
import {itemInfo} from './campaign-growth-data.mjs';
import {ensureArchiveArt,archiveFrame} from './archive-ui-art.mjs';
const rects={on:[29,149,458,239],off:[540,149,458,239],rail:[1035,215,473,106],thumb:[163,629,181,264],gift:[1098,602,355,332]};
function art(name){const [x,y,w,h]=rects[name];return `background-image:url('assets/settings/settings-controls-v1.png');background-size:${1536/w*100}% ${1024/h*100}%;background-position:${x/(1536-w)*100}% ${y/(1024-h)*100}%;`;}
const rows=[['enabled','volume','总声音','控制游戏中的全部声音'],['effectsEnabled','effectsVolume','战斗音效','施法、命中与机关反馈'],['musicEnabled','musicVolume','背景音乐','安静的月下旋律与秘境行旅']];
const actionButton=(attributes,label,cool=false,className='')=>`<button type="button" class="settings-ornate-action ${className}${cool?' settings-action-cool':''}" ${attributes}>${archiveFrame('upgrade')}<span class="settings-action-label">${label}</span></button>`;
const saveAction=(kind,label,caption)=>`<button type="button" class="settings-save-card ${kind}" data-${kind}-save><i class="settings-save-emblem" aria-hidden="true"><svg viewBox="1024 0 512 512" preserveAspectRatio="xMidYMid meet"><image href="assets/campaign-growth/ui-icons-v1.png" width="1536" height="1024"/></svg><em>${kind==='export'?'↑':'↓'}</em></i><span><strong class="settings-action-label">${label}</strong><small>${caption}</small></span><b aria-hidden="true">›</b></button>`;
export class SettingsDialog{
 constructor({storage,onSave=()=>{}}={}){this.storage=storage;this.onSave=onSave;this.prefs=audioPreferences();this.el=document.createElement('dialog');this.el.className='realm-settings';this.el.setAttribute('aria-labelledby','settings-title');this.el.innerHTML=`<div class="settings-shell"><button class="settings-close" aria-label="关闭设置">×</button><h2 id="settings-title">秘境设置</h2><nav class="settings-tabs" aria-label="设置分类"><button data-tab="audio" aria-pressed="true">声音与音乐</button><button data-tab="gift" aria-pressed="false">兑换馈赠</button><button data-tab="save" aria-pressed="false">存档迁移</button><button data-tab="performance" aria-pressed="false" data-mobile-quality-tab>触控与画质</button></nav><div class="settings-content"><section data-pane="audio" class="audio-settings">${rows.map(([enabled,volume,name,copy])=>`<div class="settings-audio-row"><div><h3>${name}</h3><p>${copy}</p></div><button type="button" class="painted-toggle" data-toggle="${enabled}" aria-label="${name}" aria-pressed="true"></button><label class="painted-range"><span class="sr-only">${name}音量</span><i class="volume-rail" style="${art('rail')}"></i><i class="volume-marker" style="${art('thumb')}"></i><input data-volume="${volume}" aria-label="${name}音量" type="range" min="0" max="100" step="1"><output></output></label></div>`).join('')}</section><section data-pane="gift" hidden><form class="gift-form"><label for="realm-gift-code">兑换码</label><div><input id="realm-gift-code" placeholder="输入获得的兑换码" autocomplete="off" maxlength="40" spellcheck="false"><button type="submit">领取馈赠</button></div></form><div class="gift-preview"><i style="${art('gift')}" aria-hidden="true"></i><div><h3>旅人的秘境馈赠</h3><p>奖励保存至本机进度，每份馈赠可领取一次。</p><div class="gift-rewards">${REDEEM_REWARDS.map(item=>{const d=itemInfo(item),x=d.icon%4,y=Math.floor(d.icon/4);return `<span><i style="background-image:url('assets/campaign-growth/items-v1.png');background-size:400% 400%;background-position:${x/3*100}% ${y/3*100}%"></i><b>${d.name} ×${item.count}</b></span>`;}).join('')}</div></div></div></section><section data-pane="save" class="save-transfer-pane" hidden><h3>携带你的秘境旅程</h3><p>导出角色、装备、灵宠、关卡和挑战冷却。导入将整体替换当前进度，操作前自动保留备份。仅在大厅使用。</p><div class="save-transfer-actions">${saveAction('export','导出存档','保存旅程副本')}${saveAction('import','导入存档','从文件恢复旅程')}</div><label><input type="checkbox" data-replace-consent> 我已确认要用所选存档替换当前进度</label></section><section data-pane="performance" class="save-transfer-pane" hidden><h3>战斗画质</h3><p>仅调整绘制清晰度与显示帧率，角色速度、伤害和跳跃保持一致。</p><div class="save-transfer-actions"><button data-quality="high" aria-pressed="false">高画质 · 60帧目标</button><button data-quality="low" aria-pressed="false">流畅 · 30帧目标</button><button type="button" data-custom-layout class="settings-layout-open">自定义按键位置</button></div><div class="settings-audio-row settings-touch-opacity"><div><h3>按键透明度</h3><p>调节摇杆和战斗按键</p></div><label class="painted-range"><span class="sr-only">按键透明度</span><i class="volume-rail" style="${art('rail')}"></i><i class="volume-marker" style="${art('thumb')}"></i><input data-control-opacity aria-label="按键透明度" type="range" min="30" max="100" step="5"><output></output></label></div></section></div><p class="settings-status" role="status" aria-live="polite">设置自动保存于当前设备</p><div class="settings-footer-actions">${actionButton('data-settings-return','返回旅程',false,'settings-done')}${actionButton('data-exit-app hidden','退出游戏',true,'realm-exit-button')}</div></div>`;
 document.body.append(this.el);this.el.querySelector('[data-custom-layout]').onclick=async()=>{try{this.controlEditor??=new MobileControlEditor({storage:this.storage});await this.controlEditor.open();}catch(e){this.status(e.message||'按键编辑界面打开失败，请重试');}};this.el.querySelector('[data-mobile-quality-tab]').hidden=!window.arcaneMobile&&!new URLSearchParams(location.search).has('touch');this.el.querySelector('[data-control-opacity]').addEventListener('input',e=>{const ok=saveControlOpacity(Number(e.target.value)/100);this.renderMobilePreferences();this.status(ok?'按键透明度已保存':'透明度已生效，暂时无法保存');});this.el.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{try{localStorage.setItem('arcane-mobile-quality',b.dataset.quality);this.renderMobilePreferences();this.status(b.dataset.quality==='low'?'已切换流畅模式':'已切换高画质模式');}catch{this.status('当前设备无法保存画质选择');}});this.el.querySelector('[data-export-save]').onclick=async()=>{try{await downloadSave(this.storage||localStorage);this.status('完整存档已交给系统保存。');}catch(e){this.status(e.message);}};this.el.querySelector('[data-import-save]').onclick=async()=>{if(!this.el.querySelector('[data-replace-consent]').checked){this.status('请先勾选整体替换确认。');return;}try{const text=await pickSave();if(!text)return;await importSave(this.storage||localStorage,text,{backup:data=>window.arcaneMobile?.bridge.saveBackup({data})});this.status('导入完成，正在重新载入…');setTimeout(()=>location.reload(),300);}catch(e){this.status(e.message);}};this.el.querySelector('.settings-close').onclick=()=>this.el.close();this.el.querySelector('[data-settings-return]').onclick=()=>this.el.close();this.el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{this.el.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));this.el.querySelectorAll('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==b.dataset.tab);});this.el.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>this.change({[b.dataset.toggle]:!this.prefs.value[b.dataset.toggle]}));this.el.querySelectorAll('[data-volume]').forEach(input=>input.addEventListener('input',()=>this.change({[input.dataset.volume]:Number(input.value)/100})));this.el.querySelector('.gift-form').onsubmit=e=>{e.preventDefault();this.redeem();};this.prefs.subscribe(()=>this.render());this.render();this.refreshActionArt();}
 status(message){this.el.querySelector('.settings-status').textContent=message;}
 change(patch){this.status(this.prefs.update(patch)?'设置已保存':'声音设置已生效，当前设备暂时无法保存');}
 render(){const p=this.prefs.value;this.el.querySelectorAll('[data-toggle]').forEach(b=>{b.setAttribute('aria-pressed',String(p[b.dataset.toggle]));b.style.cssText=art(p[b.dataset.toggle]?'on':'off');});this.el.querySelectorAll('[data-volume]').forEach(input=>{const n=Math.round(p[input.dataset.volume]*100);input.value=n;input.closest('label').querySelector('output').textContent=n+'%';input.closest('label').querySelector('.volume-marker').style.left=`calc(${n}% + ${12-.74*n}px)`;});}
 redeem(){try{const next=redeemSavedGift(this.storage,this.el.querySelector('#realm-gift-code').value);this.onSave(next);this.status('兑换成功：3张抽奖券已到账，3个中金币宝箱与3瓶中角色经验药水已放入背包。');this.el.querySelector('#realm-gift-code').value='';}catch(error){this.status(error.message);}}
 renderMobilePreferences(){let quality='high';try{quality=localStorage.getItem('arcane-mobile-quality')||quality;}catch{}this.el.querySelectorAll('[data-quality]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quality===quality)));const value=Math.round(controlOpacity()*100),input=this.el.querySelector('[data-control-opacity]');input.value=value;input.closest('label').querySelector('output').textContent=value+'%';input.closest('label').querySelector('.volume-marker').style.left=`calc(${(value-30)/70*100}% + ${12-.74*((value-30)/70*100)}px)`;}
 refreshActionArt(){if(this.actionArtPending)return;this.actionArtPending=ensureArchiveArt().then(()=>{for(const button of this.el.querySelectorAll('.settings-ornate-action')){button.querySelector('.archive-frame')?.remove();button.insertAdjacentHTML('afterbegin',archiveFrame('upgrade'));button.dataset.actionArt='ready';}}).catch(()=>{}).finally(()=>{this.actionArtPending=null;});}
 open(){this.renderMobilePreferences();this.render();this.status('设置自动保存于当前设备');this.el.showModal();this.refreshActionArt();}
}
